import Foundation

/// Taking the robot's token away, which is the one part of its Hugging Face
/// account a relayed session can reach.
///
/// Split out of ``HFAuthClient`` because the data channel carries this command and
/// none of the others: the robot cannot be *asked* about its account over the
/// relay, and it cannot be given a token there either. It can be told to drop the
/// one it has — and the relay is exactly where an owner who is nowhere near the
/// robot needs that.
///
/// **The robot goes offline and stays there.** Its token is what registers it with
/// central, so dropping it ends this session and every future one until somebody
/// re-provisions the robot over Bluetooth or through the page it serves itself.
public protocol RobotUnlinkClient: Sendable {
    func deleteHFToken() async throws
}

public extension RobotUnlinkClient {
    func deleteHFToken() async throws {
        throw URLError(.unsupportedURL)
    }
}

/// The robot's own Hugging Face account: the token it stores, the relay that
/// token buys it, and central's robot list proxied through it.
///
/// The daemon's OAuth routes (`/api/hf-auth/oauth/*`) are deliberately absent.
/// They exist for a browser pointed at the robot, and they redirect back to
/// `reachy-mini.local` — a flow this app has no use for, because it signs in
/// natively and hands the robot a token it already holds.
public protocol HFAuthClient: RobotUnlinkClient {
    func hfAuthStatus() async throws -> HFAuthStatus
    /// Stores the token on the robot. The daemon validates it against the Hub
    /// first and answers 400 if the Hub refuses it. Returns the account name it
    /// resolved to.
    @discardableResult
    func saveHFToken(_ token: String) async throws -> String?
    func relayStatus() async throws -> RelayStatus
    /// Asks the relay to reconnect. Check `didStart` before waiting on anything.
    @discardableResult
    func refreshRelay() async throws -> RelayRefresh
    /// Central's robot list, fetched by the robot with its own token.
    func centralRobotStatus() async throws -> CentralRobotStatusProxy
}

===== RobotSession+HFAuth.swift =====
   1 import Foundation
   2 
   3 /// The robot's own Hugging Face account, reached through the session.
   4 ///
   5 /// Two custody points, deliberately: this app keeps its token in the Keychain,
   6 /// and the robot keeps its own copy. Linking is what puts the second one there —
   7 /// over plain HTTP on the LAN, which is a limitation the UI has to state rather
   8 /// than hide (ADR 0001).
   9 public extension RobotSession {
  10     var canLinkHuggingFace: Bool {
  11         client is any HFAuthClient
  12     }
  13 
  14     /// Taking the token away is reachable from further than putting one there:
  15     /// the data channel carries `delete_hf_token` and nothing else about the
  16     /// account, so a relayed session can unlink a robot it can never link.
  17     var canUnlinkRobot: Bool {
  18         client is any RobotUnlinkClient
  19     }
  20 
  21     /// Cached for the life of the connection: the daemon answers this by running
  22     /// `whoami` against the Hub every time, which is a network round trip to learn
  23     /// something that changes when the user says so.
  24     func robotHFAccount(refresh: Bool = false) async throws -> HFAuthStatus {
  25         if !refresh, let cached = hfAccountCache {
  26             return cached
  27         }
  28         let status = try await withHFAuthClient { try await $0.hfAuthStatus() }
  29         hfAccountCache = status
  30         return status
  31     }
  32 
  33     /// Hands the robot a token and asks the relay to pick it up at once, rather
  34     /// than on its next retry.
  35     ///
  36     /// The returned refresh says whether anything actually restarted — on
  37     /// `skipped` there is no state change coming, so a caller must not wait for
  38     /// one.
  39     @discardableResult
  40     func linkRobot(token: String) async throws -> RelayRefresh {
  41         let username = try await withHFAuthClient { try await $0.saveHFToken(token) }
  42         // `save-token` validated the token against the Hub to answer at all, so
  43         // the account is known — asking for the status again would repeat that
  44         // same `whoami`.
  45         hfAccountCache = HFAuthStatus(isLoggedIn: true, username: username)
  46         return try await withHFAuthClient { try await $0.refreshRelay() }
  47     }
  48 
  49     /// Removes the robot's token. This app's own sign-in is untouched — signing
  50     /// out here would leave the robot reachable from outside with a token the
  51     /// user thinks they revoked.
  52     ///
  53     /// Through the narrow client, so it reaches a relayed robot too. **Over the
  54     /// relay it ends the session**: the token is what keeps the robot registered
  55     /// with central, and nothing short of re-provisioning it in person brings it
  56     /// back.
  57     func unlinkRobot() async throws {
  58         guard let client else { throw ReachyKitError.notConnected }
  59         guard let unlink = client as? any RobotUnlinkClient else {
  60             throw ReachyKitError.wirelessFeaturesUnavailable
  61         }
  62         try await unlink.deleteHFToken()
  63         hfAccountCache = nil
  64     }
  65 
  66     func relayStatus() async throws -> RelayStatus {
  67         try await withHFAuthClient { try await $0.relayStatus() }
  68     }
  69 
  70     /// Central's robot list, fetched by this robot with its own token so that no
  71     /// credential crosses the LAN.
  72     func centralRobotStatus() async throws -> CentralRobotStatusProxy {
  73         try await withHFAuthClient { try await $0.centralRobotStatus() }
  74     }
  75 }
  76 
  77 extension RobotSession {
  78     func withHFAuthClient<T>(_ call: (any HFAuthClient) async throws -> T) async throws -> T {
  79         guard let client else { throw ReachyKitError.notConnected }
  80         guard let authClient = client as? any HFAuthClient else {
  81             throw ReachyKitError.hfAuthUnavailable
  82         }
  83         return try await call(authClient)
  84     }
  85 }

