===== RobotSession.message(for:) contract =====
    /// `nonisolated` because it reads only its argument: an intent runs off the
    /// main actor and still has to render the same sentence.
    nonisolated static func describe(_ error: Error) -> String {
        let root = rootCause(of: error)
        return (root as? LocalizedError)?.errorDescription ?? root.localizedDescription
    }

    /// The sentence to show for a failed daemon call, or `nil` when there is
    /// nothing worth showing. Logs either way, and is the **only** place that
    /// does — a second logging point in the funnels would double every line.
    ///
    /// Every screen that displays a daemon failure goes through this rather than
    /// through `describe` directly. That is not a style preference: a cancelled
    /// request reads as the word "cancelled" (see `isCancellation`), so a model
    /// left to describe its own errors puts it on its own tab instead. Moving the
    /// filter into the session alone would have moved the bug, not fixed it.
    ///
    /// `nil` means *leave what is on screen alone*. An abandoned call learned
    /// nothing, so it may neither report a failure nor clear one still being read.
    nonisolated static func message(for error: Error) -> String? {
        guard !isCancellation(error) else {
            // `.public`: an error description carries no user data, and a line
            // reading `<private>` would defeat the point of keeping it.
            log.debug("dropped cancelled call: \(String(describing: error), privacy: .public)")
            return nil
        }

    /// `RobotSession.updateInfo` can never confirm success — the restart takes the
    /// in-memory job register with it — but it answers the other question: is the
    /// job still running? A Wi-Fi blip closes the same socket a restart does, and
    /// without this the screen announced a restart that never happened and then
    /// blamed the release for a version that had not moved.
    ///
    /// An unreachable daemon is the ordinary ending and keeps the old behaviour.
    /// So does a status this client does not recognise: the socket stays the end
    /// signal wherever the register says nothing useful.
    private func settleJob(_ jobID: String) async -> Bool {
        let deadline = ContinuousClock.now + jobPollBudget
        while ContinuousClock.now < deadline, !Task.isCancelled {
            guard let job = try? await session.updateInfo(jobID: jobID) else { return true }
            switch job.status {
            case .failed:
                state = .failed(String(localized: .reachy("The robot reported that the update failed.")))
                return false
            case .pending, .inProgress:
                try? await Task.sleep(for: jobPollInterval)
            case .done, .unknown:
                return true
            }
        }
        return true
    }

    private func confirmRestart(from previous: String) async {
        guard let version = await reconnect() else {
            state =
                .failed(
                    String(
                        localized: .reachy(
                            "The robot did not come back after the update. Power-cycle it and try again."
                        )
                    )
                )
            return
        }
        guard version != previous else {
            state = .failed(String(
                localized: .reachy(
                    // swiftlint:disable:next line_length
                    "The update finished but the robot still reports \(version). A new enough release may not be published yet."
                )
            ))
            return
        }
        state = .finished(version: version)
    }

    /// A cancelled call leaves the state exactly as it was: the screen the user
    /// was on went away, which is not an update failure and must not be drawn as
    /// one. `RobotSession.message(for:)` logs it either way.
    private func fail(on error: any Error) {
        guard let message = RobotSession.message(for: error) else { return }
        state = .failed(message)
    }
}

